<?php
namespace App\Livewire\LMS\Timetables;
use App\Models\{AcademicYear,School,Term,Timetable}; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Illuminate\Validation\{Rule,ValidationException}; use Jantinnerezo\LivewireAlert\Facades\LivewireAlert; use Livewire\Attributes\Layout; use Livewire\Component; use Throwable;
#[Layout('layouts.lms')]
class Index extends Component { use AuthorizesRequests; public bool $showFormModal=false,$showDeleteModal=false; public ?int $editingId=null,$deletingId=null; public string $academicYearId='',$termId='',$name='',$status='draft';
public function mount():void{$this->authorize('viewAny',Timetable::class);} public function create():void{$this->authorize('create',Timetable::class);$this->resetForm();$this->showFormModal=true;} public function edit(Timetable $timetable):void{$this->authorize('update',$timetable);$this->editingId=$timetable->id;$this->academicYearId=(string)$timetable->academic_year_id;$this->termId=(string)$timetable->term_id;$this->name=$timetable->name;$this->status=$timetable->status;$this->showFormModal=true;}
public function save():void{$timetable=$this->editingId?Timetable::findOrFail($this->editingId):null;$this->authorize($timetable?'update':'create',$timetable??Timetable::class);try{$data=$this->validate(['academicYearId'=>['required','integer',Rule::exists('academic_years','id')],'termId'=>['required','integer',Rule::exists('terms','id')],'name'=>['required','string','max:100'],'status'=>['required',Rule::in(['draft','published','archived'])]]);$year=AcademicYear::findOrFail($data['academicYearId']);abort_unless($year->school_id===School::query()->value('id')&&Term::whereKey($data['termId'])->where('academic_year_id',$year->id)->exists(),422,'Choose a term from the selected academic year.');$duplicate=Timetable::where('academic_year_id',$year->id)->where('term_id',$data['termId'])->where('name',$data['name'])->when($timetable,fn($q)=>$q->whereKeyNot($timetable->id))->exists();if($duplicate){$this->addError('name','A timetable with this name already exists for the selected term.');return;}Timetable::updateOrCreate(['id'=>$timetable?->id],['academic_year_id'=>$year->id,'term_id'=>$data['termId'],'name'=>$data['name'],'status'=>$data['status']]);$this->showFormModal=false;$this->resetForm();LivewireAlert::title($timetable?'Timetable updated':'Timetable created')->success()->asToast()->position('top-end')->show();}catch(ValidationException $e){LivewireAlert::title('Check the form')->error()->asToast()->position('top-end')->show();throw $e;}catch(Throwable $e){report($e);LivewireAlert::title('Unable to save timetable')->error()->asToast()->position('top-end')->show();}}
public function confirmDelete(Timetable $timetable):void{$this->authorize('delete',$timetable);$this->deletingId=$timetable->id;$this->showDeleteModal=true;} public function delete():void{$timetable=Timetable::findOrFail($this->deletingId);$this->authorize('delete',$timetable);try{$timetable->delete();$this->showDeleteModal=false;$this->deletingId=null;LivewireAlert::title('Timetable deleted')->success()->asToast()->position('top-end')->show();}catch(Throwable $e){report($e);LivewireAlert::title('Unable to delete timetable')->error()->asToast()->position('top-end')->show();}} public function closeModals():void{$this->showFormModal=false;$this->showDeleteModal=false;$this->resetForm();$this->resetErrorBag();} private function resetForm():void{$this->reset(['editingId','deletingId','academicYearId','termId','name','status']);$this->status='draft';$this->resetValidation();} public function render(){$years=AcademicYear::where('school_id',School::query()->value('id'))->orderByDesc('starts_at')->get();return view('livewire.lms.timetables.index',['timetables'=>Timetable::with(['academicYear','term'])->whereIn('academic_year_id',$years->pluck('id'))->latest()->get(),'years'=>$years,'terms'=>Term::whereIn('academic_year_id',$years->pluck('id'))->orderBy('sequence')->get()]);}}
